const char* GetVarint32PtrFallback(const char* p, const char* limit, uint32_t* value) {
  uint32_t result = 0;
  int shift = 0;
  while (p < limit) {
    uint8_t byte = *reinterpret_cast<const uint8_t*>(p++);
    if (shift == 28 && (byte & 0xF0) != 0) {
      // Overflow: more than 5 bytes or value too large for 32 bits
      return nullptr;
    }
    result |= (byte & 0x7F) << shift;
    if ((byte & 0x80) == 0) {
      *value = result;
      return p;
    }
    shift += 7;
  }
  return nullptr;  // Truncation: buffer ended before complete varint
}

